const PERIODS={day:'일간',week:'주간',month:'월간',quarter:'분기',year:'연간'};let DB,period='day';
const won=v=>v?`${(v/1e12).toFixed(1)}조`:'—',pct=v=>`${v>=0?'+':''}${v.toFixed(1)}%`;
function key(d,p){const x=new Date(d+'T00:00:00Z');if(p==='week'){const day=x.getUTCDay()||7;x.setUTCDate(x.getUTCDate()+(7-day));return x.toISOString().slice(0,10)}if(p==='month')return d.slice(0,7);if(p==='quarter')return `${d.slice(0,4)}-Q${Math.floor((+d.slice(5,7)-1)/3)+1}`;if(p==='year')return d.slice(0,4);return d}
function refs(market,p){const snaps=DB.snapshots.filter(x=>x.market===market).sort((a,b)=>a.date.localeCompare(b.date));const cur=snaps.at(-1);if(p==='day')return[cur,snaps.at(-2)];const groups={};snaps.forEach(s=>groups[key(s.date,p)]=s);const vals=Object.values(groups);return[cur,vals.at(-2)]}
function analyse(cur,prev){const pc={},cc={};(prev?.stocks||[]).forEach(s=>pc[s.sector]=(pc[s.sector]||0)+1);(cur?.stocks||[]).forEach(s=>cc[s.sector]=(cc[s.sector]||0)+1);const names=[...new Set([...Object.keys(pc),...Object.keys(cc)])];const sectors=names.map(name=>({name,from:pc[name]||0,to:cc[name]||0,delta:(cc[name]||0)-(pc[name]||0)})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)||b.to-a.to);return{sectors,newS:sectors.filter(x=>!x.from&&x.to),outS:sectors.filter(x=>x.from&&!x.to)}}
function summary(){const lines=[];for(const market of ['KOSPI','KOSDAQ']){const [c,p]=refs(market,period);if(!c||!p)continue;const a=analyse(c,p),up=a.sectors.find(x=>x.delta>0),down=a.sectors.find(x=>x.delta<0);let s=`${market} ${PERIODS[period]} `;if(a.newS.length)s+=`${a.newS.map(x=>x.name).join('·')} 새 등장`;else if(up)s+=`${up.name} ${up.from}→${up.to}개 확대`;else s+='산업군 구성 유지';if(a.outS.length)s+=`, ${a.outS.map(x=>x.name).join('·')} 이탈`;else if(down)s+=`, ${down.name} ${down.from}→${down.to}개 축소`;lines.push(s)}return lines.length?`${+DB.meta.latest_date.slice(5,7)}월 ${+DB.meta.latest_date.slice(8)}일 기준, ${lines.join('. ')}입니다.`:'비교 데이터가 누적되면 주도 산업군 변화를 분석합니다.'}
function renderMarket(market){const [cur,prev]=refs(market,period),a=analyse(cur,prev),node=document.querySelector('#market-template').content.cloneNode(true),sec=node.querySelector('.market');sec.querySelector('.market-kicker').textContent=market==='KOSPI'?'MAIN BOARD':'GROWTH BOARD';sec.querySelector('h2').textContent=market;sec.querySelector('.comparison').textContent=`${cur.date} ↔ ${prev?.date||'비교 데이터 없음'}`;const badges=sec.querySelector('.sector-badges');[...a.newS.map(x=>['new','NEW',x.name]),...a.outS.map(x=>['out','OUT',x.name])].forEach(([c,t,n])=>badges.insertAdjacentHTML('beforeend',`<span class="badge ${c}"><small>${t}</small>${n}</span>`));if(!badges.children.length)badges.innerHTML='<span class="badge neutral">완전 진입·이탈 없음</span>';sec.querySelector('.moves').innerHTML=a.sectors.filter(x=>x.delta).map(x=>`<div class="move"><span>${x.name}</span><span class="move-count">${x.from} → ${x.to}</span><b class="delta ${x.delta>0?'up':'down'}">${x.delta>0?'▲':'▼'}${Math.abs(x.delta)}</b></div>`).join('')||'<div class="sector">종목 수 변화가 없습니다.</div>';const pm=Object.fromEntries((prev?.stocks||[]).map(s=>[s.code,s])),cm=new Set(cur.stocks.map(s=>s.code)),outs=(prev?.stocks||[]).filter(s=>!cm.has(s.code));sec.querySelector('.out-stocks').innerHTML=outs.length?`<span class="out-label">OUT</span>${outs.map(s=>`<span>${s.name}</span>`).join('')}`:'';sec.querySelector('.stocks').innerHTML=cur.stocks.map(s=>{const old=pm[s.code],chg=old?(s.market_cap-old.market_cap)/old.market_cap*100:null,rankDelta=old?old.rank-s.rank:null;return `<article class="stock"><div class="rank">${s.rank}</div><div><div class="stock-name">${s.name} ${!old?'<span class="tag-new">NEW</span>':''}</div><div class="sector">${s.sector}</div></div><div class="meta">${old?`${old.rank}위 → ${s.rank}위 ${rankDelta?`(${rankDelta>0?'▲':'▼'}${Math.abs(rankDelta)})`:''}`:'비교시점 Top 10 밖'}<br>시총 ${won(s.market_cap)} ${chg===null?'':`· <span class="${chg>=0?'delta up':'delta down'}">${pct(chg)}</span>`}</div></article>`}).join('');return node}
function renderOverview(){const el=document.querySelector('#overview');el.innerHTML='<h2>기간별 Sector NEW / OUT</h2><div class="overview-grid"></div>';const grid=el.querySelector('.overview-grid');Object.keys(PERIODS).forEach(p=>{let html='';for(const m of ['KOSPI','KOSDAQ']){const [c,pr]=refs(m,p),a=analyse(c,pr),up=a.sectors.find(x=>x.delta>0),down=a.sectors.find(x=>x.delta<0);html+=`<div><b>${m}</b> NEW ${a.newS.map(x=>x.name).join('·')||'—'}<br>OUT ${a.outS.map(x=>x.name).join('·')||'—'}<br>확대 ${up?`${up.name} +${up.delta}`:'—'} · 축소 ${down?`${down.name} ${down.delta}`:'—'}</div>`}grid.insertAdjacentHTML('beforeend',`<article class="overview-card"><b>${PERIODS[p]}</b>${html}</article>`)})}
function render(){const overview=period==='overview';document.querySelector('#overview').classList.toggle('hidden',!overview);document.querySelector('#markets').classList.toggle('hidden',overview);if(overview){renderOverview();document.querySelector('#headline').textContent='일·주·월·분기·연간의 섹터 진입·이탈과 주요 증감을 비교합니다.';return}document.querySelector('#headline').textContent=summary();const root=document.querySelector('#markets');root.innerHTML='';['KOSPI','KOSDAQ'].forEach(m=>root.append(renderMarket(m)))}
fetch('data/history.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{if(d.meta?.status!=='ready'||!d.snapshots?.length)throw Error('pending');DB=d;document.querySelector('#asof').textContent=`${d.meta.latest_date} 종가 · 보통주 기업 Top 10`;document.querySelector('#source').textContent=`Market data: ${d.meta.source}`;document.querySelector('#market-date').textContent=`Last market date: ${d.meta.latest_date}`;document.querySelector('#freshness').textContent=`Last updated: ${new Date(d.meta.generated_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false})} KST`;render()}).catch(()=>{document.querySelector('#headline').textContent='시장 데이터를 준비하고 있습니다.';document.querySelector('#asof').textContent='데이터 준비 중';document.querySelector('#markets').innerHTML=''});document.querySelector('.periods').addEventListener('click',e=>{if(!e.target.dataset.period||!DB)return;period=e.target.dataset.period;document.querySelectorAll('.periods button').forEach(b=>b.classList.toggle('active',b===e.target));render()});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').then(r=>r.update()).catch(()=>{}));
